import numpy as np

def Bspline(xi, i, p, Xi):
    '''Inputs:
    xi : knot index, integer
    i : polynomial index, integer
    p : polynomial degree of basis function, integer
    Xi : knot vector, 1d array of arbitrary size
    Outputs:
    1d array of size 1，2 or 3
    '''
    if p == 0:
        return np.array([1.0 if Xi[i] <= xi < Xi[i+1] else 0.0])
    else:
        try:
            alpha = (xi - Xi[i]) / (Xi[i+p] - Xi[i]) if Xi[i+p]!= Xi[i] else 0.0
        except IndexError:
            alpha = 0.0
        try:
            beta = (Xi[i+p+1] - xi) / (Xi[i+p+1] - Xi[i+1]) if Xi[i+p+1]!= Xi[i+1] else 0.0
        except IndexError:
            beta = 0.0

        left_term = alpha * Bspline(xi, i, p-1, Xi)
        right_term = beta * Bspline(xi, i+1, p-1, Xi)

        return left_term + right_term
