def Rlnm(l, n, m, k, z, N_t):
    from scipy.special import sph_bess
    import numpy as np

    if l == 0 and m == 0:
        return (-1)**l * np.sqrt(2*l + 1) * sph_bess(l, k*z)

    def a_nm(n, m):
        if n < abs(m):
            return 0
        else:
            return np.sqrt((n + 1 + abs(m)) * (n + 1 - abs(m)) / ((2 * n + 1) * (2 * n + 3)))

    def b_nm(n, m):
        if n < abs(m):
            return 0
        elif 0 <= m <= n:
            return np.sqrt((n - m - 1) * (n - m) / ((2 * n - 1) * (2 * n + 1)))
        else:
            return -np.sqrt((n - m - 1) * (n - m) / ((2 * n - 1) * (2 * n + 1)))

    R = np.zeros((N_t, N_t), dtype=complex)

    for l in range(N_t):
        for n in range(N_t):
            if l == m + 1:
                R[l, m + 1] = b_nm(l, -m - 1) * R[l - 1, m] - b_nm(l + 1, m) * R[l + 1, m]
            elif l > m + 1:
                R[l, m + 1] = b_nm(l, -m - 1) * R[l - 1, m] - b_nm(l + 1, m) * R[l + 1, m]

    for l in range(N_t):
        for n in range(N_t):
            if l == 0 and n == 0:
                continue
            R[l, n - 1] = a_nm(n - 1, m) * R[l, n - 1] - a_nm(n, m) * R[l, n + 1]
            R[l, n + 1] = a_nm(l, m) * R[l + 1, n] - a_nm(l - 1, m) * R[l - 1, n]

    return R[l, n]
