def Tnvm(n, v, m, Q):
    '''Function to calculate the rotation coefficient Tnvm.
    Input
    n : int
        The principal quantum number for both expansion and reexpansion.
    m : int
        The magnetic quantum number for the reexpansion.
    v : int
        The magnetic quantum number for the expansion.
    Q : matrix of shape(3, 3)
        The rotation matrix.
    Output
    T : complex
        The rotation coefficient Tnvm.
    '''

    if m == 0:
        theta_prime, phi_prime = np.arccos(Q[2, 2]), np.arctan2(Q[2, 1], Q[2, 0])
        Y_n_minus_v = scipy.special.sph_harm(-v, n, phi_prime, theta_prime)
        T = np.sqrt(4 * np.pi / (2 * n + 1)) * Y_n_minus_v.conj()
        return T

    def a_nm(n, m):
        if n < abs(m):
            return 0
        else:
            return np.sqrt((n + 1 + abs(m)) * (n + 1 - abs(m)) / ((2 * n + 1) * (2 * n + 3)))

    def b_nm(n, m):
        if n < abs(m):
            return 0
        elif 0 <= m <= n:
            return np.sqrt((n - m - 1) * (n - m) / ((2 * n - 1) * (2 * n + 1)))
        else:
            return -np.sqrt((n - m - 1) * (n - m) / ((2 * n - 1) * (2 * n + 1)))

    Q11, Q22, Q12, Q21, Q31, Q32 = Q[0, 0], Q[1, 1], Q[0, 1], Q[1, 0], Q[2, 0], Q[2, 1]

    T_n_v_m = ((Q11 + Q22 + 1j * (Q12 - Q21)) * b_nm(n + 1, -v) * Tnvm(n, v, m - 1, Q) +
               (Q11 - Q22 + 1j * (Q12 + Q21)) * b_nm(n + 1, v) * Tnvm(n, v, m + 1, Q) -
               2 * (Q31 + 1j * Q32) * a_nm(n, v) * Tnvm(n, v, m, Q)) / (2 * b_nm(n + 1, -m - 1))

    return T_n_v_m
