def OneCycle(g, pref, spc_init, Rs, T):
    import numpy as np
    from math import *
    from scipy.optimize import root_scalar

    N, R = g.shape
    spc_end = np.copy(spc_init)
    Rs_end = np.copy(Rs)
    time_elapsed = 0.0

    while time_elapsed < T and np.sum(Rs_end) > 0:
        alive = Rs_end > 0
        g_temp, r_temp = SpeciesGrowth(g, pref, Rs_end, alive)

        # Check if any species have zero growth rate
        if np.all(g_temp == 0):
            break

        # Calculate the time until the next resource depletion
        def resource_depletion_time(Rs, g_temp, r_temp, spc_end):
            depletion_times = []
            for r in range(R):
                if r_temp[r] > 0:
                    depletion_time = -Rs[r] / (g_temp[r_temp[r]-1] * spc_end[r_temp[r]-1])
                    depletion_times.append(depletion_time)
                else:
                    depletion_times.append(np.inf)
            return np.min(depletion_times)

        time_to_next_event = min(resource_depletion_time(Rs_end, g_temp, r_temp, spc_end), T - time_elapsed)

        # Update species abundance and resource levels
        for i in range(N):
            if g_temp[i] > 0:
                spc_end[i] *= np.exp(g_temp[i] * time_to_next_event)

        for i in range(R):
            if r_temp[i] > 0:
                Rs_end[r_temp[i]-1] -= g_temp[i] * spc_end[i] * time_to_next_event

        time_elapsed += time_to_next_event

    return spc_end, Rs_end
