def apply_channel(K, rho, sys=None, dim=None):
    if sys is None:
        sys = list(range(len(dim)))

    full_dim = np.prod(dim)
    eye = np.eye(full_dim)

    for k in K:
        if sys is not None:
            operator = np.eye(full_dim)
            for s in sys:
                indices = [s] if not isinstance(s, list) else s
                for i in indices:
                    id_parts = [np.eye(d) for d in dim]
                    id_parts[i] = k
                    operator = tensor(*id_parts)
