def assign_normals(xyzs):
    import numpy as np
    import numpy.linalg as la

    natoms = len(xyzs)
    normed_cross_avg = np.zeros((natoms, 3))

    for i in range(natoms):
        neighbors = []
        for j in range(natoms):
            if i!= j:
                neighbors.append(xyzs[j] - xyzs[i])

        if len(neighbors) >= 3:
            cross_products = []
            for k in range(3):
                cross_products.append(np.cross(neighbors[k], neighbors[(k+1) % 3]))

            avg_cross = np.mean(cross_products, axis=0)
            normed_cross = avg_cross / la.norm(avg_cross)

            if xyzs[i, 2] > 0:
                normed_cross *= -1

            normed_cross_avg[i] = normed_cross

    return normed_cross_avg
