def apply_channel(K, rho, sys=None, dim=None):
    import numpy as np
    from scipy.linalg import logm

    if sys is None:
        sys = list(range(len(dim)))

    full_dim = np.prod(dim)
    identity_matrix = np.eye(full_dim)

    for i, ki in enumerate(K):
        if sys is not None:
            identity_parts = []
            for j, d in enumerate(dim):
                if j in sys:
                    identity_parts.append(ki)
                else:
                    identity_parts.append(np.eye(d))
            ki_full = np.kron(np.kron(*identity_parts[:sys[0]]), np.kron(*identity_parts[sys[0]:]))
        else:
            ki_full = ki

        rho = ki_full @ rho @ ki_full.conj().T

    return rho
